// Rendering baselines for the real-agent corpus (test/corpus, see SOURCES.md).
//
// Each document's patch (generated by ReadoutCore and kept current by
// CorpusTests) is rendered in WebKit, light and dark, with every lazy
// renderer (code highlighting, KaTeX, Mermaid) settled. Two baselines per
// document and theme:
//
//   snapshots/<doc>-<theme>.json  the whole document: every block's slot,
//                                 position, height, a hash of its text, and a
//                                 fingerprint of the computed styles and sizes
//                                 of everything inside it.
//                                 Small, exact and diffable in review.
//   screenshots/<doc>-<theme>.png pixels of the first 1200 px, compared
//                                 with a small anti-aliasing tolerance.
//
// (Full-page pixel baselines for 30 documents would add ~100 MB to the
// repository per rendering change; the snapshot covers the whole page
// instead, and full-page screenshots are always written to
// test/out/corpus/full for review, uploaded by CI as an artifact.)
//
// On a mismatch: the changed blocks are listed, the actual image and a diff
// image are written to test/out/corpus, and the run fails.
//
// Usage: node test/corpus.test.mjs [--update] [name-filter]
//   --update  rewrite baselines. Baselines must come from CI's WebKit (fonts
//             differ between machines): use the corpus-actual artifact.
import { webkit } from 'playwright';
import http from 'node:http';
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs';
import { extname, join } from 'node:path';
import { PNG } from 'pngjs';
import pixelmatch from 'pixelmatch';

const args = process.argv.slice(2);
const update = args.includes('--update');
const filter = args.find(a => !a.startsWith('--')) || '';

const CORPUS = 'test/corpus';
const SNAPS = `${CORPUS}/snapshots`;
const SHOTS = `${CORPUS}/screenshots`;
const OUT = 'test/out/corpus';
for (const d of [SNAPS, SHOTS, OUT, `${OUT}/full`, `${OUT}/actual/snapshots`, `${OUT}/actual/screenshots`]) mkdirSync(d, { recursive: true });

const WIDTH = 900;
const TOP = 1200;                  // px of pixel baseline per document
const TILE = 8000;                 // WebKit caps a capture at 32767 px
// Anti-aliasing differs by a few pixels between otherwise identical runs; a
// real rendering change moves far more than this.
const PIXEL_THRESHOLD = 0.1;       // per-pixel color distance (pixelmatch)
const MAX_DIFF_RATIO = 0.0005;     // share of pixels allowed to differ

const types = { '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.woff2': 'font/woff2', '.woff': 'font/woff', '.ttf': 'font/ttf' };
const server = http.createServer((req, res) => {
  const p = join('build/Web', decodeURIComponent(req.url.split('?')[0]));
  if (!existsSync(p)) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'content-type': types[extname(p)] || 'application/octet-stream' });
  res.end(readFileSync(p));
}).listen(0);
const base = `http://127.0.0.1:${server.address().port}`;

const browser = await webkit.launch();
const docs = readdirSync(`${CORPUS}/patches`).filter(f => f.endsWith('.json') && f.includes(filter)).sort();
let failures = 0;
const summary = [];

// Polls from Node: page.waitForFunction evaluates its function as a string
// after the first try, which the reader's CSP forbids (it then fails as if
// it had timed out).
async function until(page, fn, ms) {
  for (const end = Date.now() + ms; Date.now() < end; await page.waitForTimeout(50)) if (await page.evaluate(fn)) return;
  throw new Error('timeout');
}

async function render(patch, dark, debug = process.env.CORPUS_DEBUG === '1') {
  const page = await browser.newPage({ viewport: { width: WIDTH, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.addInitScript(dbg => {
    window.__debugParts = dbg;
    // Deterministic highlighting on a busy CI machine (see highlight.js).
    window.READOUT_TOKENIZE_LIMIT = 60000;
    // Mermaid draws some straight lines as curves with random control points
    // (same pixels, different markup): a seeded generator makes it repeatable.
    let seed = 0x2545f491;
    Math.random = () => {
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    window.__msgs = [];
    window.webkit = { messageHandlers: { readout: { postMessage: m => window.__msgs.push(m) } } };
  }, debug);
  await page.goto(`${base}/reader.html`);
  await until(page, () => window.readout && window.__msgs.some(m => m.type === 'ready'), 30000);
  await page.evaluate(d => window.readout.setAppearance({ dark: d, accent: '#0a84ff', width: 'narrow', fontSize: 16 }), dark);
  await page.evaluate(p => window.readout.apply(p), patch);
  // Large documents use content-visibility, so chunks never scrolled near
  // keep estimated heights. Lay every chunk out as one near the screen is
  // (not contained, its table headers sticky), for a page that is the same
  // on every run. (Removing the class instead left some chunks laid out and
  // others not, depending on timing.)
  await page.addStyleTag({ content: '#ro-doc.cv > .chunk:not(.near) { content-visibility: visible !important; } #ro-doc.cv > .chunk:not(.near) .table-wrap:not(.scrolls) thead th, #ro-doc.cv > .chunk:not(.near) .table-wrap.scrolls :is(td, th):first-child { position: sticky !important; }' });
  // Walk the page so every lazy renderer fires, then wait until none is pending.
  const walk = async () => {
    const height = await page.evaluate(() => document.scrollingElement.scrollHeight);
    for (let y = 0; y < height; y += 800) {
      await page.evaluate(top => window.scrollTo(0, top), y);
      await page.waitForTimeout(20);
    }
  };
  await walk();
  // A table far down a large document is measured when it comes on screen
  // (whether it scrolls): bring each one there, in turn, for a frame.
  const tables = await page.evaluate(() => document.querySelectorAll('.table-wrap').length);
  for (let i = 0; i < tables; i++) {
    await page.evaluate(i => new Promise(r => {
      document.querySelectorAll('.table-wrap')[i].scrollIntoView({ block: 'center' });
      requestAnimationFrame(() => requestAnimationFrame(() => setTimeout(r, 0)));
    }), i);
  }
  // A block can be passed before its observer fires (a fast walk on a cold
  // page), or before its highlighting arrives (a block out of reach is no
  // longer asked for): bring each one still waiting into view, one at a
  // time, and let it be done (code: highlighted, in the worker) before the next.
  for (let round = 0; round < 400; round++) {
    const waiting = await page.evaluate(() => {
      // Content of a closed <details> renders when it is opened, not before.
      const next = [...document.querySelectorAll('.code-block[data-hl="pending"], .mermaid-block:not(.done):not(.busy)')]
        .find(e => !e.querySelector('.mermaid-error') && !e.closest('details:not([open])'));
      next?.scrollIntoView({ block: 'center' });
      if (next?.classList.contains('code-block')) next.dataset.walk = '';
      return !!next;
    });
    if (!waiting) break;
    await page.waitForTimeout(50);
    await until(page, () => !document.querySelector('.code-block[data-walk][data-hl="pending"]'), 20000).catch(() => {});
    await page.evaluate(() => { for (const e of document.querySelectorAll('[data-walk]')) delete e.dataset.walk; });
  }
  await until(page, () =>
    ![...document.querySelectorAll('.code-block[data-hl="pending"], .mermaid-block.busy')]
      .some(e => !e.closest('details:not([open])'))
    && [...document.querySelectorAll('.mermaid-block')].every(b => b.classList.contains('done') || b.querySelector('.mermaid-error') || b.closest('details:not([open])'))
    && !document.querySelector('.math:not(.done), .math-block:not(.done)'),
  30000).catch(async () => {
    const left = await page.evaluate(() => [...document.querySelectorAll('.code-block[data-hl="pending"], .mermaid-block:not(.done), .math:not(.done), .math-block:not(.done)')]
      .slice(0, 5).map(e => `${e.className}${e.dataset.lang ? ` (${e.dataset.lang}: ${e.dataset.hl})` : ''}`));
    errors.push(`lazy rendering did not settle within 30 s: ${left.join('; ')}`);
  });
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(200);

  const snapshot = await page.evaluate(() => {
    // The computed properties that decide how an element looks or behaves
    // (layout, paint, overflow, interaction), for every element and its
    // generated content (::before, ::after, list markers). Not all ~350:
    // highlighted code has thousands of elements and that takes minutes.
    const PROPS = ['display', 'position', 'z-index', 'float', 'box-sizing', 'width', 'height', 'min-width', 'max-width',
      'top', 'right', 'bottom', 'left', 'margin-top', 'margin-right', 'margin-bottom', 'margin-left',
      'padding-top', 'padding-right', 'padding-bottom', 'padding-left',
      'border-top-width', 'border-top-style', 'border-top-color', 'border-right-width', 'border-right-style', 'border-right-color',
      'border-bottom-width', 'border-bottom-style', 'border-bottom-color', 'border-left-width', 'border-left-style', 'border-left-color',
      'border-top-left-radius', 'border-top-right-radius', 'border-bottom-left-radius', 'border-bottom-right-radius',
      'outline-style', 'outline-width', 'outline-color', 'box-shadow',
      'overflow-x', 'overflow-y', 'text-overflow', 'clip-path', 'visibility', 'opacity', 'transform', 'filter', 'mix-blend-mode',
      'background-color', 'background-image', 'background-clip', 'color',
      'font-family', 'font-size', 'font-weight', 'font-style', 'font-variant-numeric', 'line-height', 'letter-spacing', 'word-spacing',
      'text-align', 'text-indent', 'text-transform', 'text-decoration-line', 'text-decoration-color', 'vertical-align',
      'white-space', 'word-break', 'overflow-wrap', 'line-break', 'direction', 'writing-mode',
      'list-style-type', 'list-style-position', 'table-layout', 'border-collapse', 'object-fit',
      'cursor', 'pointer-events', 'user-select', 'content'];
    const props = cs => PROPS.map(k => cs.getPropertyValue(k)).join(';');
    // A block's own element is described by every computed property: what it
    // inherits from the page (text rendering, kerning, smoothing, …) reaches
    // all of its content, and it is one element per block, so it is cheap.
    const allProps = cs => { let out = ''; for (let i = 0; i < cs.length; i++) out += `${cs[i]}:${cs.getPropertyValue(cs[i])};`; return out; };
    const fnv = s => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
    let origin = null;   // the block being described: positions are relative to it
    const describe = el => {
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      const at = origin ? `@${Math.round(r.left - origin.left)},${Math.round(r.top - origin.top)}` : '';
      let out = `${el.tagName}.${el.getAttribute('class') || ''}|${origin ? props(cs) : allProps(cs)}|${Math.round(r.width)}x${Math.round(r.height)}${at}`;
      for (const pseudo of ['::before', '::after', ...(el.tagName === 'LI' ? ['::marker'] : [])]) {
        const ps = getComputedStyle(el, pseudo);
        if (ps.content && ps.content !== 'none' && ps.content !== 'normal' || pseudo === '::marker') out += `|${pseudo}:${props(ps)}`;
      }
      return out;
    };
    const top0 = document.getElementById('ro-doc').getBoundingClientRect().top + window.scrollY;
    const blocks = [...document.querySelectorAll('#ro-doc > .chunk > .blk, #ro-doc > .chunk > .del-mark')].map(b => {
      origin = null;
      const parts = [describe(b)];
      origin = b.getBoundingClientRect();
      for (const el of b.querySelectorAll('*')) if (!el.closest('svg') || el.tagName === 'svg') parts.push(describe(el));
      // Diagrams: the whole SVG markup, with Mermaid's generated ids numbered
      // in order of appearance and coordinates to 0.1 px, so the nodes, edges
      // and fills of every diagram are compared, not just its box.
      for (const svg of b.querySelectorAll('svg')) {
        const ids = new Map();
        for (const el of svg.querySelectorAll('[id]')) if (!ids.has(el.id)) ids.set(el.id, `id${ids.size}`);
        if (svg.id && !ids.has(svg.id)) ids.set(svg.id, `id${ids.size}`);
        let markup = svg.outerHTML;
        // Longest first, so an id that prefixes another is not replaced inside it.
        for (const [id, n] of [...ids].sort((a, b) => b[0].length - a[0].length)) markup = markup.split(id).join(n);
        parts.push(markup.replace(/-?\d+\.\d+/g, x => (Math.round(parseFloat(x) * 10) / 10).toString()));
      }
      const r = b.getBoundingClientRect();
      return {
        slot: +b.dataset.slot || 0, kind: (b.className.match(/k-(\w+)/) || [, 'del'])[1],
        top: Math.round(r.top + window.scrollY - top0), h: Math.round(r.height),
        style: fnv(parts.join('\n')),
        content: fnv(b.textContent),
        ...(window.__debugParts ? { parts } : {}),
        text: b.textContent.replace(/\s+/g, ' ').trim().slice(0, 48),
      };
    });
    return { height: document.scrollingElement.scrollHeight, blocks };
  });

  const top = await page.screenshot({ animations: 'disabled', caret: 'hide', fullPage: true,
    clip: { x: 0, y: 0, width: WIDTH, height: Math.min(TOP, snapshot.height) } });
  const tiles = [];
  for (let y = 0; y < snapshot.height; y += TILE) {
    tiles.push(await page.screenshot({ fullPage: true, animations: 'disabled', caret: 'hide',
      clip: { x: 0, y, width: WIDTH, height: Math.min(TILE, snapshot.height - y) } }));
  }
  await page.close();
  return { snapshot, top, tiles, errors };
}

function compareSnapshot(name, got) {
  const path = `${SNAPS}/${name}.json`;
  const text = JSON.stringify(got, null, 1) + '\n';
  writeFileSync(`${OUT}/actual/snapshots/${name}.json`, text);
  if (update) { writeFileSync(path, text); return null; }
  if (!existsSync(path)) return 'no snapshot baseline';
  const want = JSON.parse(readFileSync(path, 'utf8'));
  const changes = [];
  if (want.height !== got.height) changes.push(`page height ${want.height} -> ${got.height}`);
  if (want.blocks.length !== got.blocks.length) changes.push(`blocks ${want.blocks.length} -> ${got.blocks.length}`);
  const n = Math.min(want.blocks.length, got.blocks.length);
  let shown = 0;
  for (let i = 0; i < n && shown < 8; i++) {
    const a = want.blocks[i], b = got.blocks[i];
    const what = [];
    if (a.h !== b.h) what.push(`height ${a.h} -> ${b.h}`);
    if (a.style !== b.style) what.push('styles/inner layout');
    if (a.kind !== b.kind) what.push(`kind ${a.kind} -> ${b.kind}`);
    if (a.slot !== b.slot) what.push(`slot ${a.slot} -> ${b.slot}`);
    if (a.content !== b.content) what.push(`text "${a.text}" -> "${b.text}"`);
    // A moved block whose own height and styles are unchanged only follows an earlier change.
    if (!what.length && a.top !== b.top && changes.length === 0) what.push(`top ${a.top} -> ${b.top}`);
    if (what.length) { shown++; changes.push(`#${i} ${b.kind} "${b.text}": ${what.join(', ')}`); }
  }
  return changes.length ? changes.join('\n      ') : null;
}

function compareTop(name, png) {
  const shot = `${name}.png`;
  writeFileSync(`${OUT}/actual/screenshots/${shot}`, png);
  if (update) { writeFileSync(`${SHOTS}/${shot}`, png); return null; }
  if (!existsSync(`${SHOTS}/${shot}`)) return 'no screenshot baseline';
  const want = PNG.sync.read(readFileSync(`${SHOTS}/${shot}`));
  const got = PNG.sync.read(png);
  if (want.width !== got.width || want.height !== got.height) {
    writeFileSync(`${OUT}/${shot}`, png);
    return `screenshot size ${got.width}x${got.height} != baseline ${want.width}x${want.height}`;
  }
  const diff = new PNG({ width: got.width, height: got.height });
  const changed = pixelmatch(want.data, got.data, diff.data, got.width, got.height, { threshold: PIXEL_THRESHOLD });
  if (changed / (got.width * got.height) <= MAX_DIFF_RATIO) return null;
  writeFileSync(`${OUT}/${shot}`, png);
  writeFileSync(`${OUT}/${name}.diff.png`, PNG.sync.write(diff));
  return `top ${TOP}px differs in ${changed} px (${(changed / (got.width * got.height) * 100).toFixed(3)}%)`;
}

// The browser's first page meets cold caches (fonts, compiled code) and has
// rendered the first document's code blocks differently from every later
// run; render one page and throw it away before measuring anything.
if (docs.length) await render(JSON.parse(readFileSync(`${CORPUS}/patches/${docs[0]}`, 'utf8')), false);

for (const file of docs) {
  const doc = file.replace(/\.json$/, '');
  const patch = JSON.parse(readFileSync(`${CORPUS}/patches/${file}`, 'utf8'));
  for (const theme of ['light', 'dark']) {
    const name = `${doc}-${theme}`;
    const { snapshot, top, tiles, errors } = await render(patch, theme === 'dark');
    tiles.forEach((png, i) => writeFileSync(`${OUT}/full/${name}-${i + 1}.png`, png));
    const problems = [...errors];
    const s = compareSnapshot(name, snapshot);
    if (s) problems.push(s);
    const t = compareTop(name, top);
    if (t) problems.push(t);
    if (problems.length) {
      failures++;
      summary.push(name);
      console.log(`FAIL: ${name}\n      ${problems.join('\n      ')}`);
      if (s && !update) {
        // Render it again, with every element's description, so a failure
        // says whether it repeats and what exactly differs (still a failure).
        const again = await render(patch, theme === 'dark', true);
        const repeats = JSON.stringify(again.snapshot.blocks.map(b => b.style)) === JSON.stringify(snapshot.blocks.map(b => b.style));
        console.log(`      second render ${repeats ? 'gives the same result' : 'differs from the first: the page is not deterministic'}`);
        writeFileSync(`${OUT}/${name}.parts.json`, JSON.stringify(again.snapshot, null, 1));
      }
    } else {
      console.log(`${update ? 'updated' : 'ok'}: ${name} (${snapshot.blocks.length} blocks, ${snapshot.height} px)`);
    }
  }
}

await browser.close();
server.close();
if (summary.length) console.log(`changed: ${summary.join(', ')}\nActual baselines: ${OUT}/actual; diffs and full pages: ${OUT}.`);
console.log(`${docs.length} documents x 2 themes, ${failures} failing`);
process.exit(failures ? 1 : 0);
